// ============================================================
// n8n Code Node: Webcam Effect Payload Generator
// ============================================================
// PURPOSE: Takes a clean video and generates an NCA Toolkit
//          FFmpeg compose payload that makes it look like it
//          was recorded on a cheap webcam.
//
// ─────────────────────────────────────────────────────────────
// ⚙️  ADJUST THESE — values from 0.0 (none) to 1.0 (maximum)
// ─────────────────────────────────────────────────────────────

const INTENSITY = {
  noise:       0.2,   // Film grain / sensor noise
  exposure:    0.3,   // Overexposure + brightness flicker
  contrast:    0.3,   // Contrast & gamma push
  blur:        0.3,   // Soft focus / cheap lens blur
  compression: 0.3,   // Compression artefacts (higher = worse quality)
  stutter:     0.6,   // Frequency of frame-freeze stutters
  reverb:      0.5,   // Room reverb / mic echo
};

// ─────────────────────────────────────────────────────────────
// Everything below is automatic — no need to touch it
// ─────────────────────────────────────────────────────────────

const videoUrl      = $input.first().json.file_url;
const videoDuration = $input.first().json.duration || 120;
const fps = 30;

// Clamp helper so values outside 0–1 never break the math
const clamp = (v) => Math.min(1, Math.max(0, v));
const i     = Object.fromEntries(
  Object.entries(INTENSITY).map(([k, v]) => [k, clamp(v)])
);

// ────────────────────────────────────────────────────────────
// LERP the 0-1 intensities into the real parameter ranges
// lerp(min, max, t)  →  min at t=0, max at t=1
// ────────────────────────────────────────────────────────────

const lerp  = (min, max, t) => min + (max - min) * t;
const lerpR = (min, max, t) => +(lerp(min, max, t)).toFixed(4);
const lerpI = (min, max, t) => Math.round(lerp(min, max, t));

// Still randomised within a narrow band around the chosen intensity
const band = (min, max, t, spread = 0.15) => {
  const centre = lerp(min, max, t);
  const half   = (max - min) * spread;
  return Math.min(max, Math.max(min, centre + (Math.random() * 2 - 1) * half));
};

const config = {
  // — Grain / noise —
  noiseStrength: Math.round(band(10, 17, i.noise)),

  // — Exposure —
  baseBrightness:    +band(0.005, 0.08,  i.exposure).toFixed(4),
  brightnessOscAmp:  +band(0.002, 0.025, i.exposure).toFixed(4),
  brightnessOscHz:   +band(0.05,  0.5,   i.exposure).toFixed(3),
  brightnessOscHz2:  +band(0.3,   1.0,   i.exposure).toFixed(3),
  brightnessOscAmp2: +band(0.001, 0.012, i.exposure).toFixed(4),

  // — Contrast & gamma —
  contrast: +band(1.00, 1.20, i.contrast).toFixed(2),
  gamma:    +band(0.95, 1.15, i.contrast).toFixed(2),

  // — Blur —
  blurSigma: +band(0.1, 0.9, i.blur).toFixed(2),

  // — Compression (higher intensity = worse quality) —
  crf:          lerpI(18, 34, i.compression),
  maxBitrate:   `${lerpI(1500, 600, i.compression)}k`,
  audioBitrate: '96k',

  // — Stutter —
  stutterIntervalMin: lerpI(120, 20, i.stutter),
  stutterIntervalMax: lerpI(180, 35, i.stutter),
  stutterDurMin:      lerpR(0.1, 1.0, i.stutter),
  stutterDurMax:      lerpR(0.2, 1.5, i.stutter),

  // — Reverb —
  reverbInGain:  +band(0.85, 0.72, i.reverb).toFixed(2),
  reverbOutGain: +band(0.92, 0.80, i.reverb).toFixed(2),
  reverbDelay1:  Math.round(band(8,  35,  i.reverb)),
  reverbDelay2:  Math.round(band(20, 60,  i.reverb)),
  reverbDelay3:  Math.round(band(45, 100, i.reverb)),
  reverbDecay1:  +band(0.10, 0.55, i.reverb).toFixed(2),
  reverbDecay2:  +band(0.06, 0.35, i.reverb).toFixed(2),
  reverbDecay3:  +band(0.02, 0.20, i.reverb).toFixed(2),
};

// ────────────────────────────────────────────────────────────
// STUTTER TIMESTAMPS
// ────────────────────────────────────────────────────────────

const stutterPoints = [];

if (i.stutter > 0) {
  let cursor = config.stutterIntervalMin
              + Math.random() * (config.stutterIntervalMax - config.stutterIntervalMin);

  while (cursor < videoDuration - 5) {
    const dur = config.stutterDurMin
              + Math.random() * (config.stutterDurMax - config.stutterDurMin);
    stutterPoints.push({
      time:     +cursor.toFixed(2),
      duration: +dur.toFixed(2),
    });
    cursor += config.stutterIntervalMin
            + Math.random() * (config.stutterIntervalMax - config.stutterIntervalMin);
  }
}

// ────────────────────────────────────────────────────────────
// FILTER GRAPH
// ────────────────────────────────────────────────────────────

const brightnessExpr = [
  config.baseBrightness,
  `${config.brightnessOscAmp}*sin(t*${config.brightnessOscHz}*2*PI)`,
  `${config.brightnessOscAmp2}*sin(t*${config.brightnessOscHz2}*2*PI)`,
].join('+');

const webcamFx = [
  `gblur=sigma=${config.blurSigma}`,
  `noise=alls=${config.noiseStrength}:allf=t`,
  `eq=eval=frame:brightness='${brightnessExpr}':contrast=${config.contrast}:gamma=${config.gamma}`,
].join(',');

const filters = [];

// ── Video: stutter + webcam FX ───────────────────────────────

if (stutterPoints.length === 0) {
  filters.push({ filter: `[0:v]${webcamFx}[outv]` });

} else {
  const segLabels = [];
  let segIdx = 0;
  let prevEnd = 0;

  for (const sp of stutterPoints) {
    const freezeStart = sp.time;
    const freezeEnd   = +(sp.time + sp.duration).toFixed(3);
    const oneFrameEnd = +(freezeStart + 1 / fps).toFixed(4);
    const loopCount   = Math.max(1, Math.round(sp.duration * fps) - 1);

    if (freezeStart > prevEnd) {
      filters.push({
        filter: `[0:v]trim=${prevEnd.toFixed(3)}:${freezeStart.toFixed(3)},setpts=PTS-STARTPTS[vs${segIdx}]`
      });
      segLabels.push(`[vs${segIdx}]`);
      segIdx++;
    }

    filters.push({
      filter: `[0:v]trim=${freezeStart.toFixed(3)}:${oneFrameEnd},setpts=PTS-STARTPTS,loop=${loopCount}:1:0,setpts=N/${fps}/TB[vs${segIdx}]`
    });
    segLabels.push(`[vs${segIdx}]`);
    segIdx++;

    prevEnd = freezeEnd;
  }

  filters.push({
    filter: `[0:v]trim=${prevEnd.toFixed(3)},setpts=PTS-STARTPTS[vs${segIdx}]`
  });
  segLabels.push(`[vs${segIdx}]`);

  filters.push({
    filter: `${segLabels.join('')}concat=n=${segLabels.length}:v=1:a=0[vstut]`
  });
  filters.push({ filter: `[vstut]${webcamFx}[outv]` });
}

// ── Audio: each filter gets its own object + intermediate label ──
//
// NCA Toolkit was stripping the '=' from 'aecho=...' when it
// appeared inside a comma-chained filter string. Giving every
// audio filter its own filter object (with explicit [labels])
// avoids that parsing issue entirely.

if (i.reverb > 0) {
  // Step 1 — cut sub-bass rumble
  filters.push({ filter: `[0:a]highpass=f=80[ahp]` });

  // Step 2 — room reverb (own object so 'aecho=' is never inside a chain)
  const echoArgs = [
    config.reverbInGain,
    config.reverbOutGain,
    `${config.reverbDelay1}|${config.reverbDelay2}|${config.reverbDelay3}`,
    `${config.reverbDecay1}|${config.reverbDecay2}|${config.reverbDecay3}`,
  ].join(':');
  filters.push({ filter: `[ahp]aecho=${echoArgs}[areverb]` });

  // Step 3 — pull back level so wet reflections don't clip
  filters.push({ filter: `[areverb]volume=0.95[outa]` });

} else {
  // Reverb disabled — clean pass-through
  filters.push({ filter: `[0:a]acopy[outa]` });
}

// ────────────────────────────────────────────────────────────
// ASSEMBLE PAYLOAD
// ────────────────────────────────────────────────────────────

const payload = {
  inputs:  [{ file_url: videoUrl }],
  filters,
  outputs: [{
    options: [
      { option: '-map',     argument: '[outv]' },
      { option: '-map',     argument: '[outa]' },
      { option: '-c:v',     argument: 'libx264' },
      { option: '-crf',     argument: String(config.crf) },
      { option: '-maxrate', argument: config.maxBitrate },
      { option: '-bufsize', argument: '1000k' },
      { option: '-preset',  argument: 'medium' },
      { option: '-c:a',     argument: 'aac' },
      { option: '-b:a',     argument: config.audioBitrate },
      { option: '-ar',      argument: '44100' },
    ]
  }],
  metadata: {
    thumbnail: true,
    filesize:  true,
    duration:  true,
    bitrate:   true,
    encoder:   true,
  },
  id: `webcam-fx-${Date.now()}`,
};

return [{
  json: {
    payload,
    stutterPoints,
    config,
    intensity: INTENSITY,
  }
}];
